import React, { createContext, useState, useEffect, useContext } from 'react';

const AppContext = createContext();

const API_BASE = import.meta.env.VITE_API_BASE || 'http://localhost:5000/api';

export const AICTE_LOGO_SVG = `data:image/jpeg;base64,`;

export const AppProvider = ({ children }) => {
  const [companies, setCompanies] = useState([]);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [templates, setTemplates] = useState([]);
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [campaigns, setCampaigns] = useState([]);
  const [currentCampaign, setCurrentCampaign] = useState(null);
  const [candidates, setCandidates] = useState([]);
  const [selectedCandidateIds, setSelectedCandidateIds] = useState([]);
  const [step, setStep] = useState(1);
  const [recentActivity, setRecentActivity] = useState([]);
  const [loading, setLoading] = useState(false);

  // Fetch initial data on load
  useEffect(() => {
    loadCompanies();
    loadCampaigns();
    loadTemplates();
    loadRecentActivity();
  }, []);

  // Whenever companies load, set a default selected company if not set
  useEffect(() => {
    if (companies.length > 0 && !selectedCompany) {
      const quillon = companies.find(c => c.name.toLowerCase().includes('quillon'));
      setSelectedCompany(quillon || companies[0]);
    }
  }, [companies, selectedCompany]);

  // Load activities from local storage (or mock them initially)
  const loadRecentActivity = () => {
    const stored = localStorage.getItem('offerflow_activity');
    if (stored) {
      setRecentActivity(JSON.parse(stored));
    } else {
      const initial = [
        { id: 1, name: 'Q4_Engineers_Final.csv', status: 'success', time: 'Oct 12, 2023 • 128 rows' },
        { id: 2, name: 'Sales_Interns_Batch2.csv', status: 'success', time: 'Oct 10, 2023 • 12 rows' },
        { id: 3, name: 'Marketing_Lead_Import.csv', status: 'danger', time: 'Failed: Invalid schema' }
      ];
      setRecentActivity(initial);
      localStorage.setItem('offerflow_activity', JSON.stringify(initial));
    }
  };

  const addActivity = (name, status, time) => {
    const newAct = { id: Date.now(), name, status, time };
    const updated = [newAct, ...recentActivity.slice(0, 4)];
    setRecentActivity(updated);
    localStorage.setItem('offerflow_activity', JSON.stringify(updated));
  };

  // API Call: Fetch all companies
  const loadCompanies = async () => {
    try {
      const res = await fetch(`${API_BASE}/companies`);
      const data = await res.json();
      setCompanies(data);
      // Sync selectedCompany if it exists
      if (selectedCompany) {
        const found = data.find(c => c._id === selectedCompany._id);
        if (found) setSelectedCompany(found);
      } else if (data.length > 0) {
        const quillon = data.find(c => c.name.toLowerCase().includes('quillon'));
        setSelectedCompany(quillon || data[0]);
      }
    } catch (err) {
      console.error('Error fetching companies:', err);
    }
  };

  // API Call: Save/Create Company Profile
  const saveCompany = async (companyData) => {
    setLoading(true);
    try {
      const isEdit = companyData._id;
      const url = isEdit ? `${API_BASE}/companies/${companyData._id}` : `${API_BASE}/companies`;
      const method = isEdit ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyData)
      });
      const saved = await res.json();
      await loadCompanies();
      if (!isEdit || selectedCompany?._id === saved._id) {
        setSelectedCompany(saved);
      }
      setLoading(false);
      return saved;
    } catch (err) {
      console.error('Error saving company:', err);
      setLoading(false);
      throw err;
    }
  };

  // API Call: Delete Company Profile
  const deleteCompany = async (id) => {
    try {
      await fetch(`${API_BASE}/companies/${id}`, { method: 'DELETE' });
      await loadCompanies();
      if (selectedCompany?._id === id) {
        setSelectedCompany(null);
      }
    } catch (err) {
      console.error('Error deleting company:', err);
    }
  };

  // API Call: Fetch templates
  const loadTemplates = async () => {
    try {
      const res = await fetch(`${API_BASE}/templates`);
      const data = await res.json();
      setTemplates(data);
    } catch (err) {
      console.error('Error fetching templates:', err);
    }
  };

  // API Call: Save/Update template
  const saveTemplate = async (templateData) => {
    try {
      const isEdit = templateData._id;
      const url = isEdit ? `${API_BASE}/templates/${templateData._id}` : `${API_BASE}/templates`;
      const method = isEdit ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(templateData)
      });
      const saved = await res.json();
      await loadTemplates();
      setSelectedTemplate(saved);
      return saved;
    } catch (err) {
      console.error('Error saving template:', err);
      throw err;
    }
  };

  // API Call: Fetch campaigns
  const loadCampaigns = async () => {
    try {
      const res = await fetch(`${API_BASE}/campaigns`);
      const data = await res.json();
      setCampaigns(data);
    } catch (err) {
      console.error('Error fetching campaigns:', err);
    }
  };

  // API Call: Create new campaign
  const createCampaign = async (name, companyId, templateId = null) => {
    try {
      const res = await fetch(`${API_BASE}/campaigns`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, companyId, templateId })
      });
      const newCamp = await res.json();
      await loadCampaigns();
      setCurrentCampaign(newCamp);
      setCandidates([]);
      setSelectedCandidateIds([]);
      setStep(1); // Set to step 1 (upload CSV) on new campaign creation
      return newCamp;
    } catch (err) {
      console.error('Error creating campaign:', err);
      throw err;
    }
  };

  // API Call: Delete campaign
  const deleteCampaign = async (id) => {
    try {
      await fetch(`${API_BASE}/campaigns/${id}`, { method: 'DELETE' });
      await loadCampaigns();
      if (currentCampaign?._id === id) {
        setCurrentCampaign(null);
        setCandidates([]);
        setSelectedCandidateIds([]);
        setStep(1);
      }
    } catch (err) {
      console.error('Error deleting campaign:', err);
    }
  };

  // API Call: Load candidates of a campaign
  const loadCandidates = async (campaignId) => {
    if (!campaignId) return;
    try {
      const res = await fetch(`${API_BASE}/campaigns/${campaignId}/candidates`);
      const data = await res.json();
      setCandidates(data);
      // Auto select validated candidates by default
      const validated = data.filter(c => c.status === 'Validated').map(c => c._id);
      setSelectedCandidateIds(validated);
    } catch (err) {
      console.error('Error loading candidates:', err);
    }
  };

  // API Call: Upload batch candidates (from CSV parse)
  const uploadCandidates = async (campaignId, candidatesData) => {
    try {
      const res = await fetch(`${API_BASE}/campaigns/${campaignId}/candidates`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(candidatesData)
      });
      const data = await res.json();
      await loadCandidates(campaignId);
      await loadCampaigns(); // Refresh campaign stats
      return data;
    } catch (err) {
      console.error('Error batch uploading candidates:', err);
      throw err;
    }
  };

  // API Call: Add single candidate (Add Row)
  const addCandidate = async (candidateData) => {
    try {
      const res = await fetch(`${API_BASE}/campaigns/candidates`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(candidateData)
      });
      const saved = await res.json();
      await loadCandidates(candidateData.campaignId);
      await loadCampaigns(); // Refresh stats
      return saved;
    } catch (err) {
      console.error('Error adding candidate:', err);
      throw err;
    }
  };

  // API Call: Update candidate (Inline edit)
  const updateCandidate = async (candidateId, updatedData) => {
    try {
      const res = await fetch(`${API_BASE}/campaigns/candidates/${candidateId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedData)
      });
      const saved = await res.json();
      // Update state locally to avoid full fetch stutter
      setCandidates(prev => prev.map(c => c._id === candidateId ? saved : c));
      return saved;
    } catch (err) {
      console.error('Error updating candidate:', err);
      throw err;
    }
  };

  // API Call: Delete candidate
  const deleteCandidate = async (candidateId, campaignId) => {
    try {
      await fetch(`${API_BASE}/campaigns/candidates/${candidateId}`, { method: 'DELETE' });
      // Update state locally
      setCandidates(prev => prev.filter(c => c._id !== candidateId));
      setSelectedCandidateIds(prev => prev.filter(id => id !== candidateId));
      await loadCampaigns(); // Refresh stats
    } catch (err) {
      console.error('Error deleting candidate:', err);
    }
  };

  // API Call: Test SMTP configuration
  const testSmtp = async (smtpConfig) => {
    try {
      const res = await fetch(`${API_BASE}/email/test-smtp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ smtp: smtpConfig })
      });
      return await res.json();
    } catch (err) {
      console.error('Error testing SMTP:', err);
      return { success: false, message: err.message };
    }
  };

  // API Call: Trigger campaign dispatch (Nodemailer loop)
  const triggerEmailDispatch = async (campaignId, candidateIds, delayMs, retryOnFailure) => {
    try {
      const res = await fetch(`${API_BASE}/email/send-campaign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ campaignId, candidateIds, delayMs, retryOnFailure })
      });
      const data = await res.json();
      await loadCampaigns();
      return data;
    } catch (err) {
      console.error('Error sending offer letters:', err);
      throw err;
    }
  };

  return (
    <AppContext.Provider
      value={{
        companies,
        selectedCompany,
        setSelectedCompany,
        saveCompany,
        deleteCompany,
        templates,
        selectedTemplate,
        setSelectedTemplate,
        saveTemplate,
        campaigns,
        currentCampaign,
        setCurrentCampaign,
        createCampaign,
        deleteCampaign,
        candidates,
        setCandidates,
        selectedCandidateIds,
        setSelectedCandidateIds,
        loadCandidates,
        uploadCandidates,
        addCandidate,
        updateCandidate,
        deleteCandidate,
        step,
        setStep,
        recentActivity,
        addActivity,
        testSmtp,
        triggerEmailDispatch,
        loadCampaigns,
        loading
      }}
    >
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => useContext(AppContext);
